with w as (select o.operation_id, o.opened_at_ms, case when o.opened_at_ms>=1778320800000 and o.opened_at_ms<1778324400000 then 'reference_10_11' when o.opened_at_ms>=1778324400000 and o.opened_at_ms<1778328000000 then 'incident_11_12' end period
 from logical_operations o join service_routes r using(route_id) join services s on s.service_id=r.service_id where s.service_code='ledger-sync' and o.opened_at_ms>=1778320800000 and o.opened_at_ms<1778328000000),
oc as (select w.period, w.opened_at_ms, e.operation_id, e.completed_at_ms, e.attempt_count, f.is_success, c.pool_id, c.cell_id from w join outcome_events e using(operation_id) join execution_cells c on c.cell_id=e.cell_id and w.opened_at_ms>=c.effective_from_ms and (c.effective_to_ms is null or w.opened_at_ms<c.effective_to_ms) join failure_codes f on f.code_id=e.final_code_id where w.period is not null)
