 sum(attempt_count>1) retried_operations, round(100.0*sum(attempt_count>1)/count(*),4) retry_pct, round(avg(completed_at_ms-opened_at_ms),4) mean_latency_ms
from oc join worker_pools p on p.pool_id=oc.pool_id group by oc.period, p.pool_code order by 1,2;
EOF
